import React, { useState, useMemo, useEffect } from 'react';
import Header from '../components/Header';
import PortfolioCard from '../components/PortfolioCard';
import SearchBar from '../components/SearchBar';
import PortfolioModal from '../components/PortfolioModal';
import TagFilter from '../components/TagFilter';
import type { PortfolioItem } from '../types';
import DotLogo from '../components/DotLogo';
import { db } from '../index';
import { collection, getDocs, query, orderBy, writeBatch, doc } from 'firebase/firestore';
import { portfolioItems as initialProjects } from '../data/portfolioItems';


type Theme = 'light' | 'dark';

const ITEMS_TO_LOAD = 20;

interface PortfolioScreenProps {
    isLoggedIn: boolean;
    onNavigateToAdmin: () => void;
}

const AddIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24" strokeWidth={2} stroke="currentColor" {...props}>
      <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
    </svg>
);

const BLANK_PROJECT: PortfolioItem = {
    id: '',
    projectName: '',
    client: '',
    team: '',
    date: new Date().toISOString().split('T')[0],
    generalSubject: '',
    specificSubject: '',
    targetAudience: '',
    methodologies: [],
    media: [],
    otherResources: [],
    di: '',
    dm: '',
    mvpLink: '',
    imageUrl: '',
    tags: [],
};

const PortfolioScreen: React.FC<PortfolioScreenProps> = ({ isLoggedIn, onNavigateToAdmin }) => {
  const [portfolioItems, setPortfolioItems] = useState<PortfolioItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeFilters, setActiveFilters] = useState<Record<string, string | null>>({});
  const [selectedItem, setSelectedItem] = useState<PortfolioItem | null>(null);
  const [isCreatingNewItem, setIsCreatingNewItem] = useState(false);
  const [randomPhrase, setRandomPhrase] = useState('Navegue por um universo de propostas visuais e metodológicas para seu projeto educacional. 🎨');
  const [visibleCount, setVisibleCount] = useState(ITEMS_TO_LOAD);
  const [theme, setTheme] = useState<Theme>(() => {
    const savedTheme = localStorage.getItem('portfolio-theme') as Theme;
    return savedTheme || 'dark';
  });

  useEffect(() => {
    const loadProjects = async () => {
        setLoading(true);
        try {
            const projectsCollection = collection(db, 'projects');
            const q = query(projectsCollection, orderBy('date', 'desc'));
            let projectSnapshot = await getDocs(q);

            if (projectSnapshot.empty && initialProjects.length > 0) {
                console.log("Empty collection detected. Seeding database with initial projects...");
                const batch = writeBatch(db);
                initialProjects.forEach(item => {
                    const { id, ...projectData } = item; 
                    const docRef = doc(collection(db, "projects")); 
                    batch.set(docRef, projectData);
                });
                await batch.commit();
                console.log("Database seeded successfully. Re-fetching projects...");
                projectSnapshot = await getDocs(q);
            }

            const projectList = projectSnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            } as PortfolioItem));
            setPortfolioItems(projectList);

        } catch (error) {
            console.error("Error fetching or seeding portfolio items: ", error);
        } finally {
            setLoading(false);
        }
    };

    loadProjects();
  }, []);

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'light') {
      root.classList.remove('dark');
    } else {
      root.classList.add('dark');
    }
    localStorage.setItem('portfolio-theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme((prevTheme) => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const handleCardClick = (item: PortfolioItem) => {
    setSelectedItem(item);
    setIsCreatingNewItem(false);
  };

  const handleOpenCreateModal = () => {
    setSelectedItem(BLANK_PROJECT);
    setIsCreatingNewItem(true);
  };

  const handleCloseModal = () => {
    setSelectedItem(null);
    setIsCreatingNewItem(false);
  };

  const handleUpdateProject = (updatedProject: PortfolioItem) => {
    setPortfolioItems(prevItems => 
        prevItems.map(item => item.id === updatedProject.id ? updatedProject : item)
    );
  };

  const handleProjectAdded = (newProject: PortfolioItem) => {
    // Add the new project to the start of the list to maintain sort order
    setPortfolioItems(prevItems => [newProject, ...prevItems]);
  };

  const handleDeleteProject = (projectId: string) => {
      setPortfolioItems(prevItems => prevItems.filter(item => item.id !== projectId));
  };


  const filterTags = [
    'Data', 'Projeto', 'Time', 'Cliente', 'DI', 'DM', 'Assunto geral',
    'Assunto específico', 'Público-alvo', 'Metodologias', 'Mídias', 'Outros recursos'
  ];

  const tagToFieldMap: { [key: string]: keyof PortfolioItem } = {
    'Time': 'team',
    'Cliente': 'client',
    'Data': 'date',
    'Projeto': 'projectName',
    'DI': 'di',
    'DM': 'dm',
    'Assunto geral': 'generalSubject',
    'Assunto específico': 'specificSubject',
    'Público-alvo': 'targetAudience',
    'Metodologias': 'methodologies',
    'Mídias': 'media',
    'Outros recursos': 'otherResources',
  };

  // FIX: Added explicit string types and improved value processing to ensure 'values' is correctly inferred as string[]
  // and uniqueValues elements are recognized as strings for methods like .split().
  const filterOptions = useMemo(() => {
    const options: Record<string, string[]> = {};
    filterTags.forEach(tag => {
        const field = tagToFieldMap[tag];
        if (field) {
            const values: string[] = portfolioItems.flatMap((item: PortfolioItem): string[] => {
                const value = item[field];
                if (!value) {
                    return [];
                }
                if (Array.isArray(value)) {
                    // Ensure all elements in the array are converted to strings
                    return value.map(v => String(v)).filter(Boolean);
                }
                // Convert single values to string and wrap in an array
                const strVal = String(value);
                return strVal ? [strVal] : [];
            });

            const uniqueValues: string[] = [...new Set(values)].sort();

            if (tag === 'Data' && uniqueValues.length > 0) {
                options[tag] = uniqueValues.map((dateStr: string) => {
                    const parts = dateStr.split('-');
                    if (parts.length === 3) {
                        const [year, month, day] = parts;
                        return `${day}/${month}/${year}`;
                    }
                    return dateStr;
                });
            } else if (uniqueValues.length > 0) {
              options[tag] = uniqueValues;
            }
        }
    });
    return options;
  }, [portfolioItems]);

  const handleFilterChange = (category: string, value: string | null) => {
    setActiveFilters(prev => ({ ...prev, [category]: value }));
  };

  const handleClearAllFilters = () => {
      setActiveFilters({});
      setSearchTerm('');
  };

  // FIX: Added robust type guards and string conversions to prevent runtime errors during filtering.
  // This ensures that operations like .split() or .includes() are performed on strings,
  // and handles potentially non-string array elements from Firestore.
  const filteredItems = useMemo(() => {
    let items = portfolioItems;

    // 1. Apply active dropdown filters
    const activeFilterKeys = Object.keys(activeFilters).filter(key => activeFilters[key]);
    if (activeFilterKeys.length > 0) {
        items = items.filter(item => {
            return activeFilterKeys.every(filterKey => {
                const filterValue = activeFilters[filterKey];
                const fieldKey = tagToFieldMap[filterKey];
                if (!fieldKey || !filterValue) return true;

                const itemValue = item[fieldKey];

                if (fieldKey === 'date' && typeof itemValue === 'string') {
                    const parts = itemValue.split('-');
                    if (parts.length === 3) {
                        const [year, month, day] = parts;
                        const formattedDate = `${day}/${month}/${year}`;
                        return formattedDate === filterValue;
                    }
                }

                if (Array.isArray(itemValue)) {
                    return itemValue.map(String).includes(filterValue);
                }
                return String(itemValue) === filterValue;
            });
        });
    }

    // 2. Apply global search term on the already filtered list
    const term = searchTerm.toLowerCase();
    if (!term) {
        return items;
    }

    return items.filter(
      (item) =>
        (item.projectName || '').toLowerCase().includes(term) ||
        (item.client || '').toLowerCase().includes(term) ||
        (item.team || '').toLowerCase().includes(term) ||
        (item.di || '').toLowerCase().includes(term) ||
        (item.dm || '').toLowerCase().includes(term) ||
        (item.generalSubject || '').toLowerCase().includes(term) ||
        (item.specificSubject || '').toLowerCase().includes(term) ||
        (item.targetAudience || '').toLowerCase().includes(term) ||
        (item.tags && Array.isArray(item.tags) && item.tags.some(tag => String(tag || '').toLowerCase().includes(term))) ||
        (item.methodologies && Array.isArray(item.methodologies) && item.methodologies.some(m => String(m || '').toLowerCase().includes(term))) ||
        (item.media && Array.isArray(item.media) && item.media.some(m => String(m || '').toLowerCase().includes(term))) ||
        (item.otherResources && Array.isArray(item.otherResources) && item.otherResources.some(r => String(r || '').toLowerCase().includes(term)))
    );
  }, [searchTerm, portfolioItems, activeFilters]);

  useEffect(() => {
    const handleScroll = () => {
      if (selectedItem) return; // Don't load more items when modal is open

      const nearBottom = window.innerHeight + window.scrollY >= document.body.offsetHeight - 500;

      if (nearBottom && visibleCount < filteredItems.length) {
        setVisibleCount(prevCount => prevCount + ITEMS_TO_LOAD);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [visibleCount, filteredItems.length, selectedItem]);

  useEffect(() => {
    window.scrollTo(0, 0);
    setVisibleCount(ITEMS_TO_LOAD);
  }, [searchTerm, activeFilters]);

  return (
    <div className={`bg-gray-50 dark:bg-zinc-900 min-h-screen transition-colors duration-300`}>
      <Header theme={theme} toggleTheme={toggleTheme} isLoggedIn={isLoggedIn} onNavigateToAdmin={onNavigateToAdmin} />

      <div className="text-center py-20 bg-gray-100 dark:bg-zinc-800 border-b border-gray-200 dark:border-zinc-700/50">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <h2 className="text-3xl sm:text-4xl text-zinc-800 dark:text-gray-100 font-semibold lg:w-3/5 mx-auto">
                {randomPhrase}
            </h2>
          </div>
      </div>

      <main className="container mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <SearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} placeholder="Buscar por projeto, cliente, tecnologia..." />

        <TagFilter 
            tags={filterTags}
            options={filterOptions}
            activeFilters={activeFilters}
            onFilterChange={handleFilterChange}
            onClearAll={handleClearAllFilters}
        />

        {loading ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                {Array.from({ length: 8 }).map((_, index) => (
                    <div key={index} className="h-80 bg-gray-200 dark:bg-zinc-800 rounded-lg animate-pulse"></div>
                ))}
            </div>
        ) : filteredItems.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                {filteredItems.slice(0, visibleCount).map((item) => (
                    <PortfolioCard key={item.id} item={item} onClick={handleCardClick} theme={theme} />
                ))}
            </div>
        ) : (
            <div className="text-center py-16">
                <h3 className="text-xl font-semibold text-zinc-800 dark:text-gray-200">Nenhum projeto encontrado</h3>
                <p className="text-gray-500 dark:text-gray-400 mt-2">Tente ajustar seus filtros ou o termo de busca.</p>
            </div>
        )}
      </main>

      {isLoggedIn && (
        <button
            onClick={handleOpenCreateModal}
            className="fixed bottom-8 right-8 bg-accent hover:bg-accent-dark text-white dark:text-zinc-900 rounded-full p-4 shadow-lg hover:shadow-xl transition-all duration-300 transform hover:scale-110 z-50"
            aria-label="Adicionar novo projeto"
        >
            <AddIcon className="w-8 h-8" />
        </button>
      )}

      {selectedItem && (
        <PortfolioModal
          item={selectedItem}
          onClose={handleCloseModal}
          theme={theme}
          isCreating={isCreatingNewItem}
          isLoggedIn={isLoggedIn}
          onUpdate={handleUpdateProject}
          onAdd={handleProjectAdded}
          onDelete={handleDeleteProject}
        />
      )}
    </div>
  );
};

export default PortfolioScreen;

import React, { useState, useEffect } from 'react';
import DotLogo from '../components/DotLogo';
import { db } from '../index';
import { collection, addDoc, serverTimestamp, getDocs, query, orderBy, writeBatch, doc } from 'firebase/firestore';
import { User } from 'firebase/auth';
import type { PortfolioItem } from '../types';

// PapaParse and XLSX are loaded from a CDN script in index.html
declare const Papa: any;
declare const XLSX: any;

interface AdminScreenProps {
  user: User;
  onLogout: () => void;
  onNavigate: () => void;
}

interface UploadLog {
    id: string;
    timestamp: {
        seconds: number;
        nanoseconds: number;
    } | null;
    fileName: string;
}

interface PortfolioStats {
    totalProjects: number;
    lastUpdated: string | null;
    topClient: string;
}

const getGoogleSlidesPreviewUrl = (url: string): string | null => {
    if (typeof url !== 'string' || !url.includes('docs.google.com/presentation/d/')) {
        return null;
    }
    // Match the base URL including the presentation ID, and discard any extra parameters like /edit, ?usp=sharing, #slide=id.p, etc.
    const presentationMatch = url.match(/(https:\/\/docs\.google\.com\/presentation\/d\/[a-zA-Z0-9-_]+)/);
    if (!presentationMatch || !presentationMatch[1]) {
        return null;
    }
    const baseUrl = presentationMatch[1];

    // Generate an embeddable URL for an iframe.
    return `${baseUrl}/pubembed?start=false&loop=false&delayms=3000`;
};

const UploadIcon: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
